--Query to find original sales price for items on that were missing pricing in SFCC, Spring missing prices
SELECT 
	idc.RetailVariantId,
	idc.ItemId,
	id.inventcolorid,
	idc.pacRetailPrice
FROM 
	inventdimcombination idc
JOIN 
	INVENTDIM id
		ON idc.inventdimid = id.inventdimid
			AND idc.dataareaid = id.dataareaid
WHERE
	idc.RetailVariantId IN ('0010007015','0010007016','0010007019','0010007023','0010007024','0010007027','0010007028','0010007029','0010007031','0010007032','0010007033','0010007034','0010007035','0010007037','0010007041','0010007042','0010007043','0010007045','0010007048','0010007050','0010007051','0010007054','0010007055','0010007056','0010007057','0010007058','0010007059','0010007062','0010007065','0010007067','0010007068','0010007071','0010007072','0010007073','0010007076','0010007078','0010007079','0010007080','0010007082','0010007083','0010007084','0010007086','0010007087','0010007088','0010007089','0010007091','0010007093','0010007094','0010007097','0010007098','0010007099','0010007104','0010007105','0010007109','0010007112','0010007120','0010007121','0010007126','0010007128','0010007129','0010007130','0010007134','0010007137','0010007141','0010007145','0010007147','0010007063','0010007070','0010007081','0010007085','0010007096','0010007111','0010007114','0010007125','0010007142','0010007018','0010007020','0010007021','0010007022','0010007030','0010007036','0010007038','0010007040','0010007046','0010007047','0010007049','0010007052','0010007053','0010007060','0010007077','0010007090','0010007095','0010007100','0010007101','0010007102','0010007103','0010007106','0010007107','0010007108','0010007115','0010007116','0010007117','0010007118','0010007122','0010007123','0010007124','0010007127','0010007135','0010007136','0010007138','0010007139','0010007140','0010007144','0010007146','0010007148','0010007110','0010007143','0010007025','0010007026','0010007039','0010007044','0010007061','0010007064','0010007066','0010007069','0010007074','0010007075','0010007092','0010007113','0010007119','0010007131','0010007132','0010007133')
ORDER BY 
	idc.ItemId, idc.RetailVariantId

--Query to find original sales price for items on that were missing pricing in SFCC, Edikted missing prices
SELECT 
	--idc.RetailVariantId,
	DISTINCT idc.ItemId,
	id.inventcolorid,
	idc.pacRetailPrice
FROM 
	inventdimcombination idc
JOIN 
	INVENTDIM id
		ON idc.inventdimid = id.inventdimid
			AND idc.dataareaid = id.dataareaid
WHERE 
	idc.RetailVariantId IN ('0010008845','0010008846','0010008847','0010008848','0010008849','0010008895','0010008896','0010008897','0010008898','0010008899','0010008915','0010008916','0010008917','0010008918','0010008919','0010008970','0010008971','0010008972','0010008973','0010008974','0010008980','0010008981','0010008982','0010008983','0010008984','0010008820','0010008821','0010008822','0010008823','0010008824','0010008825','0010008826','0010008827','0010008828','0010008829','0010008830','0010008831','0010008832','0010008833','0010008834','0010008835','0010008836','0010008837','0010008838','0010008839','0010008840','0010008841','0010008842','0010008843','0010008844','0010008850','0010008851','0010008852','0010008853','0010008854','0010008855','0010008856','0010008857','0010008858','0010008859','0010008860','0010008861','0010008862','0010008863','0010008864','0010008885','0010008886','0010008887','0010008888','0010008889','0010008890','0010008891','0010008892','0010008893','0010008894','0010008900','0010008901','0010008902','0010008903','0010008904','0010008905','0010008906','0010008907','0010008908','0010008909','0010008910','0010008911','0010008912','0010008913','0010008914','0010008920','0010008921','0010008922','0010008923','0010008924','0010008945','0010008946','0010008947','0010008948','0010008949','0010008950','0010008951','0010008952','0010008953','0010008954','0010008955','0010008956','0010008957','0010008958','0010008959','0010008960','0010008961','0010008962','0010008963','0010008964','0010008965','0010008966','0010008967','0010008968','0010008969','0010008975','0010008976','0010008977','0010008978','0010008979','0010008985','0010008986','0010008987','0010008988','0010008989','0010008990','0010008991','0010008992','0010008993','0010008994','0010008995','0010008996','0010008997','0010008998','0010008999')
